head.script:
tailwind.config = {
  darkMode: 'class',
  theme: {
    extend: {
      fontFamily: {
        cyber: ['Orbitron', 'sans-serif'],
        space: ['Space Grotesk', 'sans-serif'],
        mono: ['JetBrains Mono', 'monospace'],
        tech: ['Rajdhani', 'sans-serif'],
      }
    }
  }
}

head.b:skin:
/* Reset default blogger widgets & navbar */
.navbar, #navbar, .widget-item-control, .quickedit, .status-msg-wrap { display: none !important; }
body {
  margin: 0;
  padding: 0;
  background-color: #040609 !important;
  color: #e2e8f0;
  font-family: 'Space Grotesk', system-ui, sans-serif;
  overflow-x: hidden;
}

/* Cyber Glows & Glassmorphism */
.glass-panel {
  background: rgba(8, 14, 26, 0.75);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(0, 240, 255, 0.18);
}
.glass-panel-crimson {
  background: rgba(20, 6, 12, 0.75);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 0, 85, 0.3);
}
.glass-card-hover {
  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}
.glass-card-hover:hover {
  transform: translateY(-4px);
  border-color: rgba(0, 240, 255, 0.5);
  box-shadow: 0 10px 30px -10px rgba(0, 240, 255, 0.3), 0 0 1px 1px rgba(0, 240, 255, 0.3);
}
.cyber-grid {
  background-size: 40px 40px;
  background-image: 
    linear-gradient(to right, rgba(0, 240, 255, 0.04) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(0, 240, 255, 0.04) 1px, transparent 1px);
}
.animate-scan {
  animation: scanAnim 2.5s ease-in-out infinite;
}
@keyframes scanAnim {
  0% { top: 0%; opacity: 0.8; }
  50% { top: 96%; opacity: 1; }
  100% { top: 0%; opacity: 0.8; }
}
@keyframes pulseGlowAnim {
  0%, 100% { opacity: 0.6; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.03); }
}
.animate-pulse-glow {
  animation: pulseGlowAnim 4s ease-in-out infinite;
}
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-track { background: #040609; }
::-webkit-scrollbar-thumb { background: #152238; border-radius: 4px; border: 1px solid rgba(0, 240, 255, 0.2); }
::-webkit-scrollbar-thumb:hover { background: rgba(0, 240, 255, 0.5); }

body.script:
const { useState, useEffect, useRef } = React;

// SVG Icons
const Icons = {
  Download: (props) => <svg className={props.className || "w-4 h-4"} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>,
  Zap: (props) => <svg className={props.className || "w-4 h-4"} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"/></svg>,
  Shield: (props) => <svg className={props.className || "w-4 h-4"} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>,
  Terminal: (props) => <svg className={props.className || "w-4 h-4"} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="4 17 10 11 4 5"/><line x1="12" y1="19" x2="20" y2="19"/></svg>,
  Layers: (props) => <svg className={props.className || "w-4 h-4"} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polygon points="12 2 2 7 12 12 22 7 12 2"/><polyline points="2 17 12 22 22 17"/><polyline points="2 12 12 17 22 12"/></svg>,
  Monitor: (props) => <svg className={props.className || "w-4 h-4"} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="2" y="3" width="20" height="14" rx="2" ry="2"/><line x1="8" y1="21" x2="16" y2="21"/><line x1="12" y1="17" x2="12" y2="21"/></svg>,
  Menu: (props) => <svg className={props.className || "w-4 h-4"} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="3" y1="12" x2="21" y2="12"/><line x1="3" y1="6" x2="21" y2="6"/><line x1="3" y1="18" x2="21" y2="18"/></svg>,
  X: (props) => <svg className={props.className || "w-4 h-4"} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>,
  Check: (props) => <svg className={props.className || "w-4 h-4"} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>,
  Home: (props) => <svg className={props.className || "w-4 h-4"} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="m3 9 9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><polyline points="9 22 9 12 15 12 15 22"/></svg>,
  Sparkles: (props) => <svg className={props.className || "w-4 h-4"} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="m12 3-1.912 5.813a2 2 0 0 1-1.275 1.275L3 12l5.813 1.912a2 2 0 0 1 1.275 1.275L12 21l1.912-5.813a2 2 0 0 1 1.275-1.275L21 12l-5.813-1.912a2 2 0 0 1-1.275-1.275L12 3Z"/></svg>,
  Cpu: (props) => <svg className={props.className || "w-4 h-4"} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="4" y="4" width="16" height="16" rx="2"/><rect x="9" y="9" width="6" height="6"/><line x1="9" y1="1" x2="9" y2="4"/><line x1="15" y1="1" x2="15" y2="4"/><line x1="9" y1="20" x2="9" y2="23"/><line x1="15" y1="20" x2="15" y2="23"/><line x1="20" y1="9" x2="23" y2="9"/><line x1="20" y1="14" x2="23" y2="14"/><line x1="1" y1="9" x2="4" y2="9"/><line x1="1" y1="14" x2="4" y2="14"/></svg>,
  DollarSign: (props) => <svg className={props.className || "w-4 h-4"} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg>
};

// Metallic Logo Component
function MetallicLogo({ size = 40 }) {
  return (
    <div style={{ width: size, height: size }} className="relative flex items-center justify-center rounded-xl bg-gradient-to-br from-cyan-500/20 via-[#0a1224] to-rose-500/20 border border-cyan-500/40 shadow-[0_0_15px_rgba(0,240,255,0.3)]">
      <span className="font-cyber font-black text-cyan-400 tracking-tighter" style={{ fontSize: size * 0.45 }}>R</span>
    </div>
  );
}

// App Main Component
function App() {
  const [activeTab, setActiveTab] = useState('overview');
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [downloadModalOpen, setDownloadModalOpen] = useState(false);
  const [donateModalOpen, setDonateModalOpen] = useState(false);
  const [terminalModalOpen, setTerminalModalOpen] = useState(false);
  const [liveTime, setLiveTime] = useState('00:00:00');

  useEffect(() => {
    const update = () => {
      const d = new Date();
      setLiveTime(d.toLocaleTimeString('en-US', { hour12: false }));
    };
    update();
    const id = setInterval(update, 1000);
    return () => clearInterval(id);
  }, []);

  const triggerConfetti = () => {
    if (typeof confetti === 'function') {
      confetti({ particleCount: 80, spread: 70, origin: { y: 0.6 } });
    }
  };

  return (
    <div className="min-h-screen bg-[#040609] text-slate-100 relative">
      {/* Background Grid & Neon Glows */}
      <div className="fixed inset-0 cyber-grid opacity-30 pointer-events-none" />
      <div className="fixed top-1/4 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[500px] h-[500px] bg-cyan-500/10 rounded-full blur-[140px] pointer-events-none" />
      <div className="fixed top-1/3 right-10 w-[350px] h-[350px] bg-rose-600/10 rounded-full blur-[120px] pointer-events-none" />

      {/* Master Top Navbar */}
      <header className="fixed top-0 left-0 right-0 w-full h-16 bg-[#080b10]/90 backdrop-blur-xl border-b border-cyan-500/20 z-50 flex items-center justify-between px-4 sm:px-6 shadow-[0_4px_30px_rgba(0,0,0,0.8)]">
        <div className="flex items-center gap-3 cursor-pointer" onClick={() => setActiveTab('overview')}>
          <MetallicLogo size={36} />
          <div>
            <div className="flex items-center gap-2">
              <span className="font-cyber font-black text-sm sm:text-base tracking-wider text-white">RITESH PC OS</span>
              <span className="px-1.5 py-0.5 rounded bg-rose-950/90 border border-rose-500/60 text-[9px] font-mono text-rose-300 font-bold">v2.0 LIVE</span>
            </div>
            <span className="text-[10px] font-mono text-cyan-400 tracking-wider uppercase font-semibold">DEBIAN 12 • KERNEL 6.12</span>
          </div>
        </div>

        {/* Desktop Navigation Links */}
        <nav className="hidden md:flex items-center gap-1 bg-[#0f172a]/70 border border-cyan-500/30 px-3 py-1 rounded-full">
          {[
            { id: 'overview', label: 'Overview', icon: Icons.Home },
            { id: 'simulator', label: 'UEFI Sandbox', icon: Icons.Monitor },
            { id: 'ecosystem', label: '3-in-1 Matrix', icon: Icons.Layers },
            { id: 'security', label: 'Security', icon: Icons.Shield },
            { id: 'bootflow', label: '15s Boot & Specs', icon: Icons.Zap },
          ].map(tab => {
            const Icon = tab.icon;
            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-mono transition-all ${
                  activeTab === tab.id
                    ? 'bg-cyan-500/25 text-cyan-300 border border-cyan-500/50 shadow-[0_0_12px_rgba(0,240,255,0.3)] font-bold'
                    : 'text-slate-300 hover:text-cyan-300 hover:bg-cyan-500/10'
                }`}
              >
                <Icon className="w-3.5 h-3.5 text-cyan-400" />
                <span>{tab.label}</span>
              </button>
            );
          })}
          <button
            onClick={() => { setDonateModalOpen(true); triggerConfetti(); }}
            className="flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-mono text-amber-300 hover:bg-amber-500/20 border border-amber-500/30 bg-amber-500/10"
          >
            <Icons.DollarSign className="w-3.5 h-3.5 text-amber-400" />
            <span>Donate UPI</span>
          </button>
        </nav>

        {/* Right Buttons */}
        <div className="flex items-center gap-2 sm:gap-3">
          <div className="hidden lg:flex font-mono text-[11px] text-emerald-400 bg-emerald-950/40 border border-emerald-500/30 px-2.5 py-1 rounded-full items-center gap-1.5">
            <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse" />
            <span>{liveTime}</span>
          </div>
          <button
            onClick={() => setDownloadModalOpen(true)}
            className="bg-gradient-to-r from-cyan-400 to-cyan-500 hover:from-cyan-300 text-slate-950 font-bold px-3.5 py-1.5 rounded-lg text-xs tracking-wider shadow-lg shadow-cyan-500/25 uppercase flex items-center gap-1.5"
          >
            <Icons.Download className="w-3.5 h-3.5" />
            <span>DOWNLOAD ISO</span>
          </button>
          <button
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            className="p-1.5 rounded-lg bg-slate-900 border border-slate-700 text-slate-300 md:hidden"
          >
            {mobileMenuOpen ? <Icons.X className="w-5 h-5" /> : <Icons.Menu className="w-5 h-5" />}
          </button>
        </div>

        {/* Mobile Drawer */}
        {mobileMenuOpen && (
          <div className="md:hidden absolute top-16 left-0 right-0 bg-[#070b14]/98 backdrop-blur-2xl border-b border-cyan-500/30 px-5 py-4 space-y-2 font-mono text-sm shadow-2xl z-50">
            {[
              { id: 'overview', label: 'Overview' },
              { id: 'simulator', label: 'UEFI Sandbox' },
              { id: 'ecosystem', label: '3-in-1 Matrix' },
              { id: 'security', label: 'Security' },
              { id: 'bootflow', label: '15s Boot & Specs' },
            ].map(item => (
              <button
                key={item.id}
                onClick={() => { setActiveTab(item.id); setMobileMenuOpen(false); }}
                className={`block w-full text-left py-2 px-3 rounded-lg ${activeTab === item.id ? 'bg-cyan-500/20 text-cyan-300 font-bold' : 'text-slate-300'}`}
              >
                {item.label}
              </button>
            ))}
            <button
              onClick={() => { setDonateModalOpen(true); setMobileMenuOpen(false); triggerConfetti(); }}
              className="block w-full text-left py-2 px-3 rounded-lg text-amber-300 bg-amber-500/10 border border-amber-500/30"
            >
              Donate UPI
            </button>
          </div>
        )}
      </header>

      {/* Main Hero & Content Section */}
      <main className="relative z-10 pt-24 pb-20 px-4 sm:px-6 lg:px-8 max-w-7xl mx-auto space-y-12">
        {/* Hero Header */}
        <div className="text-center space-y-6 pt-6">
          <div className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-[#081020]/90 backdrop-blur-xl border border-cyan-500/40 shadow-[0_0_20px_rgba(0,240,255,0.2)]">
            <span className="w-2 h-2 rounded-full bg-cyan-400 animate-pulse" />
            <span className="font-mono text-xs font-semibold text-cyan-300 uppercase">LIVE UEFI 64-BIT HYBRID KERNEL v6.12</span>
          </div>
          <h1 className="font-cyber font-black text-3xl sm:text-5xl md:text-6xl lg:text-7xl tracking-tight text-white">
            RITESH PC OS <br />
            <span className="text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 via-teal-300 to-rose-400">
              CYBERNETIC 3-IN-1 SUITE
            </span>
          </h1>
          <p className="text-slate-300 max-w-3xl mx-auto text-sm sm:text-base md:text-lg">
            Ultra-futuristic cybernetic OS engineered with 4K Frosted Glass UI, 3-in-1 combo (Debian Bookworm 12 Linux + Android Waydroid + Windows Layer), 15s instant live boot, and immutable BIOS security.
          </p>
          <div className="flex flex-wrap justify-center gap-4 pt-2">
            <button
              onClick={() => setDownloadModalOpen(true)}
              className="px-6 py-3 rounded-xl bg-gradient-to-r from-cyan-500 to-teal-400 text-slate-950 font-cyber font-bold text-sm shadow-[0_0_25px_rgba(0,240,255,0.4)] hover:scale-105 transition-transform flex items-center gap-2"
            >
              <Icons.Download className="w-4 h-4" />
              <span>DOWNLOAD HYBRID ISO</span>
            </button>
            <button
              onClick={() => setActiveTab('simulator')}
              className="px-6 py-3 rounded-xl glass-panel text-cyan-300 font-mono text-sm border border-cyan-500/40 hover:bg-cyan-500/10 transition-colors flex items-center gap-2"
            >
              <Icons.Monitor className="w-4 h-4" />
              <span>TEST UEFI SANDBOX</span>
            </button>
          </div>
        </div>

        {/* Highlights Grid */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          {[
            { title: '15s Boot Flow', desc: 'Instant NVMe RAM loading engine', icon: Icons.Zap, color: 'text-amber-400' },
            { title: '3-in-1 Ecosystem', desc: 'Debian 12 + Android + Windows Layer', icon: Icons.Layers, color: 'text-cyan-400' },
            { title: 'Immutable Security', desc: 'Chattr +i NVRAM lock & BIOS protection', icon: Icons.Shield, color: 'text-rose-400' },
            { title: '4K Frosted Glass', desc: 'Hardware accelerated compositor', icon: Icons.Sparkles, color: 'text-emerald-400' },
          ].map((item, idx) => {
            const Icon = item.icon;
            return (
              <div key={idx} className="glass-panel glass-card-hover p-5 rounded-2xl border border-cyan-500/20">
                <Icon className={`w-8 h-8 ${item.color} mb-3`} />
                <h3 className="font-cyber font-bold text-white text-base mb-1">{item.title}</h3>
                <p className="text-slate-400 text-xs font-mono">{item.desc}</p>
              </div>
            );
          })}
        </div>

        {/* Interactive Section Container */}
        <div className="glass-panel p-6 sm:p-8 rounded-3xl border border-cyan-500/30">
          <div className="flex items-center justify-between border-b border-cyan-500/20 pb-4 mb-6">
            <div>
              <h2 className="font-cyber font-bold text-xl text-white">Live System Ecosystem</h2>
              <p className="text-slate-400 text-xs font-mono">Real-time simulated architectural telemetry</p>
            </div>
            <button
              onClick={() => setTerminalModalOpen(true)}
              className="px-3 py-1.5 rounded-lg bg-slate-900 border border-cyan-500/40 text-cyan-300 text-xs font-mono flex items-center gap-1.5"
            >
              <Icons.Terminal className="w-3.5 h-3.5" />
              <span>Launch Terminal</span>
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 font-mono text-sm">
            <div className="p-4 rounded-xl bg-slate-950/60 border border-cyan-500/20 space-y-2">
              <div className="text-cyan-400 font-bold text-xs">HOST LINUX CORE</div>
              <div className="text-white text-base font-cyber">Debian Bookworm 12</div>
              <p className="text-slate-400 text-xs">Kernel 6.12 Liquorix Low-Latency Audio/Video Driver stack with Tint2 Cyber Glass Panel.</p>
            </div>
            <div className="p-4 rounded-xl bg-slate-950/60 border border-emerald-500/20 space-y-2">
              <div className="text-emerald-400 font-bold text-xs">ANDROID SUBSYSTEM</div>
              <div className="text-white text-base font-cyber">Waydroid 11 Subsystem</div>
              <p className="text-slate-400 text-xs">Zero-latency GPU shared buffer, Google Play Store integration, full touch/mouse compatibility.</p>
            </div>
            <div className="p-4 rounded-xl bg-slate-950/60 border border-rose-500/20 space-y-2">
              <div className="text-rose-400 font-bold text-xs">IMMUTABLE BOOTLOADER</div>
              <div className="text-white text-base font-cyber">Cybernetic UEFI GRUB</div>
              <p className="text-slate-400 text-xs">Hardware level priority #1 NVRAM entry, self-healing bootloader fallback scripts.</p>
            </div>
          </div>
        </div>
      </main>

      {/* Modals */}
      {/* Download Modal */}
      {downloadModalOpen && (
        <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-md flex items-center justify-center p-4">
          <div className="glass-panel p-6 sm:p-8 rounded-3xl max-w-lg w-full border border-cyan-500/50 space-y-5">
            <div className="flex justify-between items-center">
              <h3 className="font-cyber font-bold text-lg text-white">DOWNLOAD RITESH PC OS ISO</h3>
              <button onClick={() => setDownloadModalOpen(false)} className="text-slate-400 hover:text-white">
                <Icons.X className="w-5 h-5" />
              </button>
            </div>
            <div className="space-y-3 font-mono text-xs text-slate-300">
              <div className="p-3 rounded-xl bg-slate-950 border border-cyan-500/30">
                <div className="text-cyan-400 font-bold">RITESH_PC_OS_v2.0_HYBRID_X86_64.iso</div>
                <div className="text-slate-400 mt-1">Size: 3.8 GB • SHA256: 9f8a7e4b...verified</div>
              </div>
              <p className="text-slate-400">Direct download mirror hosted on ultra-fast GitHub Releases & CDN network.</p>
            </div>
            <div className="flex gap-3">
              <a
                href="https://github.com/undercoverking360-svg/RITESH_PC_OS/releases"
                target="_blank"
                className="flex-1 py-3 text-center rounded-xl bg-cyan-500 text-slate-950 font-bold font-cyber text-xs hover:bg-cyan-400"
              >
                MIRROR 1 (GITHUB DIRECT)
              </a>
              <button onClick={() => setDownloadModalOpen(false)} className="px-4 py-3 rounded-xl bg-slate-800 text-slate-300 text-xs font-mono">
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Donate Modal */}
      {donateModalOpen && (
        <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-md flex items-center justify-center p-4">
          <div className="glass-panel p-6 sm:p-8 rounded-3xl max-w-md w-full border border-amber-500/50 text-center space-y-4">
            <div className="flex justify-between items-center">
              <h3 className="font-cyber font-bold text-lg text-amber-300">SUPPORT RITESH PC OS</h3>
              <button onClick={() => setDonateModalOpen(false)} className="text-slate-400 hover:text-white">
                <Icons.X className="w-5 h-5" />
              </button>
            </div>
            <p className="text-slate-300 text-xs font-mono">Scan via any UPI App (GPay, PhonePe, Paytm) to support the project development!</p>
            <div className="p-4 rounded-2xl bg-white inline-block shadow-[0_0_20px_rgba(245,158,11,0.3)]">
              <img src="https://api.qrserver.com/v1/create-qr-code/?size=180x180&data=upi://pay?pa=riteshguru@upi&pn=RITESH_PC_OS" alt="UPI QR" className="w-40 h-40" />
            </div>
            <div className="font-mono text-xs text-amber-400 font-bold">UPI ID: riteshguru@upi</div>
          </div>
        </div>
      )}

      {/* Terminal Modal */}
      {terminalModalOpen && (
        <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-md flex items-center justify-center p-4">
          <div className="glass-panel p-5 rounded-2xl max-w-2xl w-full border border-cyan-500/50 font-mono text-xs space-y-3">
            <div className="flex justify-between items-center border-b border-cyan-500/20 pb-2">
              <span className="text-cyan-400 font-bold">root@ritesh-pc-os: ~</span>
              <button onClick={() => setTerminalModalOpen(false)} className="text-slate-400 hover:text-white">
                <Icons.X className="w-4 h-4" />
              </button>
            </div>
            <div className="bg-slate-950 p-4 rounded-xl text-emerald-400 space-y-1 h-60 overflow-y-auto">
              <div>[OK] Kernel 6.12.8-liquorix-amd64 mounted</div>
              <div>[OK] Waydroid container bridge started on lxc0</div>
              <div>[OK] Chattr +i protection activated on /boot/efi/EFI/ritesh_pc</div>
              <div>[INFO] Ready for live command inputs...</div>
            </div>
          </div>
        </div>
      )}

      {/* Footer */}
      <footer className="border-t border-cyan-500/20 bg-[#040609] py-8 text-center text-xs font-mono text-slate-500">
        <p>RITESH PC OS © 2026 • Engineered by Ritesh • Pure Debian 12 + Waydroid Hybrid Suite</p>
      </footer>
    </div>
  );
}

